import * as React from 'react';
import * as StackingCardsPrimitive from '@exhuma/core';
import { cn } from '@/lib/utils';

export interface StackingCardsProps extends React.ComponentPropsWithoutRef<typeof StackingCardsPrimitive.StackingCards> {
  className?: string;
}

export const StackingCards = React.forwardRef<HTMLDivElement, StackingCardsProps>(
  ({ className, children, ...props }, ref) => (
    <StackingCardsPrimitive.StackingCards
      ref={ref}
      className={cn(
        'relative flex flex-col gap-8 w-full max-w-2xl mx-auto',
        className
      )}
      {...props}
    >
      {children}
    </StackingCardsPrimitive.StackingCards>
  )
);
StackingCards.displayName = 'StackingCards';

