import { Component, JSX, splitProps } from 'solid-js';
import * as StackingCardsPrimitive from '@exhuma/core';

export interface StackingCardsProps extends JSX.HTMLAttributes<HTMLDivElement> {
  [key: string]: unknown;
}

export const StackingCards: Component<StackingCardsProps> = (props) => {
  const [local, others] = splitProps(props, ['class', 'children']);
  return (
    <StackingCardsPrimitive.StackingCards
      class={`relative flex flex-col gap-8 w-full max-w-2xl mx-auto ${local.class ?? ''}`}
      {...others}
    >
      {local.children}
    </StackingCardsPrimitive.StackingCards>
  );
};

