import React from 'react';
import { View, StyleSheet, type ViewProps } from 'react-native';
import * as CursorTooltipPrimitive from '@exhuma/core';

export interface CursorTooltipProps extends ViewProps {
  children?: React.ReactNode;
}

export function CursorTooltip({ style, children, ...props }: CursorTooltipProps) {
  return (
    <View style={[styles.container, style]} {...props}>
      {children}
    </View>
  );
}

